fn shell_game(n: i32, x: i8) -> i8 {
    // The moves repeat every 6 steps, forming a cycle.
    // We'll find the position after n modulo 6 moves to avoid large computations.

    // We'll precompute the position after each step in the cycle starting from initial position x.
    // Steps:
    // i odd: swap positions 0 <-> 1
    // i even: swap positions 1 <-> 2

    // Define a helper function to perform one move depending on the step parity.
    fn move_token(pos: i8, step: i32) -> i8 {
        if step % 2 == 1 {
            // odd step: swap 0 and 1
            match pos {
                0 => 1,
                1 => 0,
                2 => 2,
                _ => pos, // just in case, but input is guaranteed 0..=2
            }
        } else {
            // even step: swap 1 and 2
            match pos {
                0 => 0,
                1 => 2,
                2 => 1,
                _ => pos,
            }
        }
    }

    let cycle_length = 6;
    let steps = (n % cycle_length) as i32;

    let mut pos = x;
    for i in 1..=steps {
        pos = move_token(pos, i);
    }

    pos
}